CREATE TYPE public.app_role AS ENUM ('admin','staff','customer');
CREATE TABLE public.user_roles(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null default 'customer', unique(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '', email text not null default '', avatar_url text, preferences jsonb not null default '{}', disabled boolean not null default false,created_at timestamptz not null default now(), updated_at timestamptz not null default now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name,avatar_url,preferences) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.handle_rigor_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',''),COALESCE(NEW.email,'')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'customer'); RETURN NEW; END $$;
CREATE TRIGGER rigor_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_rigor_signup();
INSERT INTO public.profiles(id,full_name,email) SELECT id,COALESCE(raw_user_meta_data->>'full_name',''),COALESCE(email,'') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'customer'::public.app_role FROM auth.users ON CONFLICT DO NOTHING;
CREATE FUNCTION public.rigor_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE public.automations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,name text not null CHECK(length(name) BETWEEN 1 AND 120),description text not null default '',category text not null default 'Business',trigger_config jsonb not null default '{}',action_config jsonb not null default '{}',status text not null default 'draft' CHECK(status IN ('draft','active','paused','completed','failed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.automations TO authenticated; GRANT ALL ON public.automations TO service_role;
ALTER TABLE public.automations ENABLE ROW LEVEL SECURITY;
CREATE POLICY automations_own ON public.automations FOR ALL TO authenticated USING(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled)) WITH CHECK(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled));
CREATE POLICY automations_admin_read ON public.automations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.automation_executions(id uuid primary key default gen_random_uuid(),automation_id uuid not null references public.automations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,execution_status text not null CHECK(execution_status IN ('running','completed','failed')),started_at timestamptz not null default now(),completed_at timestamptz,error_message text,execution_data jsonb);
GRANT SELECT ON public.automation_executions TO authenticated; GRANT ALL ON public.automation_executions TO service_role;
ALTER TABLE public.automation_executions ENABLE ROW LEVEL SECURITY;
CREATE POLICY executions_read ON public.automation_executions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ai_agents(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,name text not null CHECK(length(name) BETWEEN 1 AND 120),description text not null default '',instructions text not null,model text not null default 'openai/gpt-6-astra',status text not null default 'inactive' CHECK(status IN ('active','inactive')),configuration jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ai_agents TO authenticated; GRANT ALL ON public.ai_agents TO service_role;
ALTER TABLE public.ai_agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY agents_own ON public.ai_agents FOR ALL TO authenticated USING(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled)) WITH CHECK(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled));
CREATE TABLE public.agent_conversations(id uuid primary key default gen_random_uuid(),agent_id uuid not null references public.ai_agents(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,prompt text not null,response text not null,created_at timestamptz not null default now());
GRANT SELECT ON public.agent_conversations TO authenticated; GRANT ALL ON public.agent_conversations TO service_role;
ALTER TABLE public.agent_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_read ON public.agent_conversations FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.integrations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,provider text not null,connection_status text not null default 'disconnected',connected_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,provider));
GRANT SELECT ON public.integrations TO authenticated; GRANT ALL ON public.integrations TO service_role;
ALTER TABLE public.integrations ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrations_read ON public.integrations FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,action text not null,description text not null,created_at timestamptz not null default now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role;
ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activity_logs FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,plan text not null default 'free' CHECK(plan IN ('free','pro','business')),subscription_status text not null default 'active',payment_provider text,started_at timestamptz not null default now(),expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_read ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null CHECK(length(name) BETWEEN 1 AND 120),email text not null,company text not null default '',service text not null,message text not null CHECK(length(message) BETWEEN 1 AND 5000),created_at timestamptz not null default now());
GRANT SELECT ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_admin ON public.contact_messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,message text not null,is_read boolean not null default false,created_at timestamptz not null default now());
GRANT SELECT ON public.notifications TO authenticated; GRANT UPDATE(is_read) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TRIGGER profiles_time BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.rigor_updated_at();
CREATE TRIGGER automations_time BEFORE UPDATE ON public.automations FOR EACH ROW EXECUTE FUNCTION public.rigor_updated_at();
CREATE TRIGGER agents_time BEFORE UPDATE ON public.ai_agents FOR EACH ROW EXECUTE FUNCTION public.rigor_updated_at();
CREATE TRIGGER integrations_time BEFORE UPDATE ON public.integrations FOR EACH ROW EXECUTE FUNCTION public.rigor_updated_at();
CREATE TRIGGER subscriptions_time BEFORE UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.rigor_updated_at();
CREATE INDEX automations_owner ON public.automations(user_id); CREATE INDEX executions_owner ON public.automation_executions(user_id,started_at DESC); CREATE INDEX agents_owner ON public.ai_agents(user_id); CREATE INDEX conversation_owner ON public.agent_conversations(user_id); CREATE INDEX activity_owner ON public.activity_logs(user_id,created_at DESC); CREATE INDEX notifications_owner ON public.notifications(user_id,created_at DESC);
CREATE FUNCTION public.rigor_log_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_logs(user_id,action,description) VALUES(COALESCE(NEW.user_id,OLD.user_id),lower(TG_OP),TG_TABLE_NAME || ': ' || COALESCE(NEW.name,OLD.name)); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER automation_log AFTER INSERT OR UPDATE OR DELETE ON public.automations FOR EACH ROW EXECUTE FUNCTION public.rigor_log_change();
CREATE TRIGGER agent_log AFTER INSERT OR UPDATE OR DELETE ON public.ai_agents FOR EACH ROW EXECUTE FUNCTION public.rigor_log_change();